using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using F=System.Windows.Forms;using System.Windows.Forms.Integration;
namespace GearLab {
 public sealed class ComponentTree:F.TreeView{
  protected override F.CreateParams CreateParams{get{var p=base.CreateParams;p.Style|=0x8000;return p;}}
  // The native checkbox double-click toggles its image without AfterCheck on .NET Framework.
  // Leave double-clicks on labels available for focusing parts; consume only checkbox hits.
  protected override void WndProc(ref F.Message m){if(m.Msg==0x0203){long point=m.LParam.ToInt64();var hit=HitTest(new Point((short)(point&65535),(short)((point>>16)&65535)));if((hit.Location&F.TreeViewHitTestLocations.StateImage)!=0){m.Result=IntPtr.Zero;return;}}base.WndProc(ref m);}
 }

 public sealed class GearViewerControl:F.UserControl {
  public readonly WpfScene Scene=new WpfScene();readonly ElementHost host=new ElementHost();readonly F.TreeView tree=new ComponentTree();readonly F.TextBox search=new F.TextBox();readonly F.ComboBox cutAxis=new F.ComboBox();readonly F.TrackBar cutPosition=new F.TrackBar();readonly F.CheckBox reverse=new F.CheckBox();readonly F.Label cutLabel=new F.Label();readonly F.Timer cutDelay=new F.Timer();readonly F.CheckBox moveParts=new F.CheckBox();readonly F.Label selectedPart=new F.Label();readonly SafeNumber[] placement=new SafeNumber[3];bool syncingPlacement;bool syncing;Result result;bool pendingHide;public event Action VisibilityChanged;
  public GearViewerControl(){
   BackColor=Color.FromArgb(246,249,252);Dock=F.DockStyle.Fill;var split=new F.SplitContainer{Size=new Size(850,600),SplitterDistance=600,Dock=F.DockStyle.Fill,FixedPanel=F.FixedPanel.Panel2,Panel1MinSize=100,Panel2MinSize=210,SplitterWidth=5};Controls.Add(split);split.SizeChanged+=(s,e)=>{if(split.Width>360)split.SplitterDistance=Math.Max(100,split.Width-245);};host.Dock=F.DockStyle.Fill;host.Child=Scene.Root;split.Panel1.Controls.Add(host);
   var panel=new F.FlowLayoutPanel{Dock=F.DockStyle.Fill,FlowDirection=F.FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new F.Padding(8),BackColor=Color.FromArgb(237,243,248)};split.Panel2.Controls.Add(panel);panel.Controls.Add(new F.Label{Text="КОМПОНЕНТЫ",Width=215,Height=24,Font=new Font("Segoe UI",10,FontStyle.Bold)});
   search.Width=215;search.AccessibleName="Поиск компонента";search.TextChanged+=(s,e)=>RebuildTree();panel.Controls.Add(search);tree.Width=215;tree.Height=290;tree.CheckBoxes=true;tree.HideSelection=false;tree.AccessibleName="Видимость компонентов 3D";tree.AfterCheck+=Checked;tree.AfterSelect+=(s,e)=>{if(e.Node.Tag is string&&!((string)e.Node.Tag).StartsWith("@"))Scene.Select((string)e.Node.Tag);else Scene.Select(null);};tree.NodeMouseDoubleClick+=(s,e)=>{if(e.Node.Tag is string&&!((string)e.Node.Tag).StartsWith("@"))Scene.FocusPart((string)e.Node.Tag);};panel.Controls.Add(tree);
   var buttons=new F.FlowLayoutPanel{Width=220,Height=64,WrapContents=true,Margin=new F.Padding(0)};buttons.Controls.Add(Button("Показать всё",103,()=>{Scene.Hidden.Clear();Scene.HideHousing=false;Changed();}));buttons.Controls.Add(Button("Механизм",103,()=>{foreach(var p in Parts())if(p.Role=="housing"||p.Role=="fastener"||p.Reference)Scene.Hidden.Add(p.Id);else Scene.Hidden.Remove(p.Id);Changed();}));buttons.Controls.Add(Button("Изолировать",103,()=>{if(tree.SelectedNode==null)return;var ids=new HashSet<string>(Ids(tree.SelectedNode));Scene.Hidden.Clear();foreach(var p in Parts())if(!ids.Contains(p.Id))Scene.Hidden.Add(p.Id);Changed();Scene.Fit();}));buttons.Controls.Add(Button("Вписать",103,()=>Scene.Fit()));panel.Controls.Add(buttons);BuildPlacementControls(panel);
   panel.Controls.Add(new F.Label{Text="КАМЕРА",Width=215,Height=24,Font=new Font("Segoe UI",10,FontStyle.Bold)});var cameras=new F.ComboBox{Width=215,DropDownStyle=F.ComboBoxStyle.DropDownList,AccessibleName="Вид камеры"};cameras.Items.AddRange(new[]{"Изометрия","Сверху","Спереди","Справа"});cameras.SelectedIndex=0;cameras.SelectedIndexChanged+=(s,e)=>{Scene.Camera.Preset((string)cameras.SelectedItem);};panel.Controls.Add(cameras);
   panel.Controls.Add(new F.Label{Text="СЕЧЕНИЕ МОДЕЛИ",Width=215,Height=24,Margin=new F.Padding(0,12,0,0),Font=new Font("Segoe UI",10,FontStyle.Bold)});cutAxis.Width=215;cutAxis.DropDownStyle=F.ComboBoxStyle.DropDownList;cutAxis.AccessibleName="Секущая плоскость";cutAxis.Items.AddRange(new[]{"Без сечения","XY · глубина по Z","XZ · сдвиг по Y","YZ · сдвиг по X"});cutAxis.SelectedIndex=0;cutAxis.SelectedIndexChanged+=(s,e)=>ApplySection();panel.Controls.Add(cutAxis);
   cutPosition.Width=215;cutPosition.Minimum=0;cutPosition.Maximum=1000;cutPosition.Value=750;cutPosition.TickStyle=F.TickStyle.None;cutPosition.AccessibleName="Положение сечения";cutPosition.ValueChanged+=(s,e)=>{UpdateSectionLabel();cutDelay.Stop();cutDelay.Start();};panel.Controls.Add(cutPosition);cutLabel.Width=215;cutLabel.Height=24;panel.Controls.Add(cutLabel);reverse.Width=215;reverse.Text="Оставить другую сторону";reverse.CheckedChanged+=(s,e)=>ApplySection();panel.Controls.Add(reverse);panel.Controls.Add(new F.Label{Text="Флажки и сечение меняют только просмотр; STEP сохраняет полную сборку.",Width=215,Height=52,ForeColor=Color.SlateGray,Font=new Font("Segoe UI",8)});
   cutDelay.Interval=120;cutDelay.Tick+=(s,e)=>{cutDelay.Stop();ApplySection();};Scene.Loaded+=()=>{if(pendingHide)SetHousingHidden(true);RebuildTree();ApplySection();};Scene.Picked+=id=>SelectNode(id);VisibleChanged+=(s,e)=>{if(!Visible)cutDelay.Stop();};
  }
  void BuildPlacementControls(F.FlowLayoutPanel panel){
   panel.Controls.Add(new F.Label{Text="ПЕРЕМЕСТИТЬ ДЕТАЛЬ",Width=215,Height=24,Font=new Font("Segoe UI",10,FontStyle.Bold)});
   moveParts.Text="Перетаскивать детали мышью";moveParts.Width=215;moveParts.Height=28;moveParts.AccessibleName="Режим перемещения деталей";moveParts.CheckedChanged+=(s,e)=>Scene.SetMoveMode(moveParts.Checked);panel.Controls.Add(moveParts);
   var axis=new F.ComboBox{Width=215,DropDownStyle=F.ComboBoxStyle.DropDownList,AccessibleName="Ось перемещения детали"};axis.Items.AddRange(new[]{"В плоскости экрана","Только X","Только Y","Только Z"});axis.SelectedIndex=0;axis.SelectedIndexChanged+=(s,e)=>Scene.MoveAxis=axis.SelectedIndex-1;panel.Controls.Add(axis);
   selectedPart.Width=215;selectedPart.Height=40;selectedPart.AutoEllipsis=true;panel.Controls.Add(selectedPart);
   for(int i=0;i<3;i++){int index=i;var row=new F.FlowLayoutPanel{Width=215,Height=30,Margin=new F.Padding(0)};row.Controls.Add(new F.Label{Text=(i==0?"X":i==1?"Y":"Z")+", мм",Width=48,Height=25,TextAlign=ContentAlignment.MiddleLeft});var n=new SafeNumber{Width=155,DecimalPlaces=2,Increment=1,Minimum=-10000,Maximum=10000,AccessibleName="Сдвиг детали "+(i==0?"X":i==1?"Y":"Z")};placement[i]=n;n.ScrollRequested=delta=>panel.AutoScrollPosition=new Point(0,Math.Max(0,-panel.AutoScrollPosition.Y-delta/3));n.ValueChanged+=(a,b)=>{if(syncingPlacement)return;var v=Scene.Offset(Scene.SelectedId);if(index==0)v.X=(double)n.Value;else if(index==1)v.Y=(double)n.Value;else v.Z=(double)n.Value;Scene.SetOffset(Scene.SelectedId,v);};row.Controls.Add(n);panel.Controls.Add(row);}
   var resets=new F.FlowLayoutPanel{Width=220,Height=32,Margin=new F.Padding(0)};resets.Controls.Add(Button("Вернуть деталь",103,()=>Scene.SetOffset(Scene.SelectedId,new System.Windows.Media.Media3D.Vector3D())));resets.Controls.Add(Button("Вернуть все",103,()=>Scene.ResetPlacements()));panel.Controls.Add(resets);
   panel.Controls.Add(new F.Label{Text="Сдвиг только для просмотра. Экспорт — в сборочном положении. Перерасчёт сбрасывает сдвиги. Esc отменяет текущее перетаскивание.",Width=215,Height=70,ForeColor=Color.SlateGray,Font=new Font("Segoe UI",8)});
   Scene.PlacementChanged+=SyncPlacement;SyncPlacement();
  }
  void SyncPlacement(){syncingPlacement=true;try{var node=Scene.Nodes.FirstOrDefault(n=>n.Part.Id==Scene.SelectedId);selectedPart.Text=node==null?"Выберите деталь в сцене или дереве":node.Part.Label;var v=Scene.Offset(Scene.SelectedId);for(int i=0;i<3;i++){placement[i].Enabled=node!=null&&Scene.Ready;placement[i].Commit((decimal)(i==0?v.X:i==1?v.Y:v.Z));}}finally{syncingPlacement=false;}}
  static F.Button Button(string text,int width,Action action){var b=new F.Button{Text=text,Width=width,Height=28,Margin=new F.Padding(0,0,4,3)};b.Click+=(s,e)=>action();return b;}
  IEnumerable<CadPart> Parts(){return result!=null&&result.Model!=null&&result.Model.Valid?result.Model.Parts:Enumerable.Empty<CadPart>();}
  static string Group(CadPart p){if(p.Reference)return "Мотор";switch(p.Role){case "housing":return "Корпус и крышки";case "fixed":return "Опорная рама";case "gear":return "Шестерни и диски";case "shaft":return "Валы и водила";case "bearing":return "Опоры и втулки";case "fastener":return "Крепёж";case "pin":case "roller":return "Пальцы и ролики";default:return "Ремень и шкивы";}}
  public void SetResult(Result value,bool async){bool differentKind=result!=null&&value!=null&&(result.P.Kind!=value.P.Kind||result.P.CycloidLayout!=value.P.CycloidLayout);result=value;if(differentKind){Scene.Hidden.Clear();Scene.HideHousing=false;pendingHide=false;}Scene.SetResult(value,async);RebuildTree();SyncPlacement();if(differentKind&&VisibilityChanged!=null)VisibilityChanged();}
  public void SetExploded(bool value){Scene.SetExploded(value);ApplySection();}
  public bool HousingHidden{get{var parts=Parts().Where(p=>p.Role=="housing").ToList();return parts.Count>0&&parts.All(p=>Scene.Hidden.Contains(p.Id));}}
  public void SetHousingHidden(bool hidden){pendingHide=hidden;foreach(var p in Parts().Where(p=>p.Role=="housing")){if(hidden)Scene.Hidden.Add(p.Id);else Scene.Hidden.Remove(p.Id);}Changed();}
  void Changed(){pendingHide=HousingHidden;Scene.HideHousing=false;Scene.RefreshVisibility();SyncChecks();if(VisibilityChanged!=null)VisibilityChanged();}
  void SyncChecks(){if(syncing)return;syncing=true;try{foreach(F.TreeNode group in tree.Nodes){foreach(F.TreeNode node in group.Nodes)node.Checked=!Scene.Hidden.Contains((string)node.Tag);group.Checked=Ids(group).All(id=>!Scene.Hidden.Contains(id));}}finally{syncing=false;}}
  void RebuildTree(){if(syncing)return;syncing=true;tree.BeginUpdate();string selected=tree.SelectedNode==null?null:tree.SelectedNode.Tag as string;string top=tree.TopNode==null?null:tree.TopNode.Tag as string;var expanded=new HashSet<string>(tree.Nodes.Cast<F.TreeNode>().Where(n=>n.IsExpanded).Select(n=>(string)n.Tag));bool first=tree.Nodes.Count==0;tree.Nodes.Clear();F.TreeNode selectedNode=null,topNode=null;string query=search.Text.Trim();foreach(var group in Parts().GroupBy(Group)){var root=new F.TreeNode(group.Key){Tag="@"+group.Key};foreach(var part in group){if(query.Length>0&&part.Label.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)<0&&part.Id.IndexOf(query,StringComparison.OrdinalIgnoreCase)<0)continue;var n=new F.TreeNode(part.Label){Tag=part.Id,Checked=!Scene.Hidden.Contains(part.Id),ToolTipText=part.Label+" · "+part.Id};root.Nodes.Add(n);if((string)n.Tag==selected)selectedNode=n;if((string)n.Tag==top)topNode=n;}if(root.Nodes.Count==0)continue;root.Checked=root.Nodes.Cast<F.TreeNode>().All(n=>n.Checked);tree.Nodes.Add(root);if((string)root.Tag==selected)selectedNode=root;if((string)root.Tag==top)topNode=root;if(first||query.Length>0||expanded.Contains((string)root.Tag))root.Expand();}tree.ShowNodeToolTips=true;if(selectedNode!=null)tree.SelectedNode=selectedNode;if(topNode!=null)tree.TopNode=topNode;tree.EndUpdate();syncing=false;}
  IEnumerable<string> Ids(F.TreeNode node){string key=node.Tag as string;if(key==null)return Enumerable.Empty<string>();if(key.StartsWith("@"))return Parts().Where(p=>Group(p)==key.Substring(1)).Select(p=>p.Id);return new[]{key};}
  void Checked(object sender,F.TreeViewEventArgs e){if(syncing)return;foreach(string id in Ids(e.Node)){if(e.Node.Checked)Scene.Hidden.Remove(id);else Scene.Hidden.Add(id);}pendingHide=HousingHidden;Changed();}
  void SelectNode(string id){if(id==null){tree.SelectedNode=null;return;}foreach(F.TreeNode group in tree.Nodes)foreach(F.TreeNode node in group.Nodes)if((string)node.Tag==id){tree.SelectedNode=node;node.EnsureVisible();return;}}
  int Axis{get{return cutAxis.SelectedIndex==1?2:cutAxis.SelectedIndex==2?1:cutAxis.SelectedIndex==3?0:-1;}}
  double Coordinate(){var b=Scene.Bounds(false);if(b.IsEmpty)return 0;int axis=Axis;double lo=axis==0?b.X:axis==1?b.Y:b.Z,size=axis==0?b.SizeX:axis==1?b.SizeY:b.SizeZ;return lo+size*cutPosition.Value/1000;}
  void UpdateSectionLabel(){cutLabel.Text=Axis<0?"Сечение выключено":(Axis==0?"X":Axis==1?"Y":"Z")+" = "+Engine.F(Coordinate())+" мм";}
  void ApplySection(){if(syncing)return;cutPosition.Enabled=Axis>=0;reverse.Enabled=Axis>=0;UpdateSectionLabel();Scene.ConfigureSection(Axis,Coordinate(),reverse.Checked);}
  public void Fit(){Scene.Fit();}public void Present(double phase){Scene.UpdatePose(phase);}
  protected override void Dispose(bool disposing){if(disposing){cutDelay.Dispose();Scene.Dispose();host.Child=null;}base.Dispose(disposing);}
 }
}
